{"name": "create_transfer_parts_function", "query": "
-- ============================================================
-- transfer_parts()
-- Transfers LEGO parts between two inventories with full
-- validation, transactional safety, and audit logging.
-- ============================================================
CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id   INTEGER,
    target_inventory_id   INTEGER,
    part_to_transfer_num  VARCHAR,
    color_to_transfer_id  INTEGER,
    quantity_to_transfer  INTEGER,
    transfer_reason       VARCHAR DEFAULT 'manual_transfer'
)
RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    -- Source inventory row variables
    v_source_qty        INTEGER;
    v_source_is_spare   BOOLEAN;

    -- Target inventory row variables
    v_target_qty        INTEGER;

    -- Existence-check flags
    v_source_inv_exists BOOLEAN := FALSE;
    v_target_inv_exists BOOLEAN := FALSE;
    v_part_exists       BOOLEAN := FALSE;
    v_color_exists      BOOLEAN := FALSE;

    -- Final return message
    v_result_msg        TEXT;

    -- Error capture
    v_error_msg         TEXT;
BEGIN
    -- ===========================================================
    -- STEP A-1 : BASIC BUSINESS-RULE VALIDATION
    -- (No locks yet – purely value checks that cannot change data)
    -- ===========================================================

    -- Prevent self-transfers
    IF source_inventory_id = target_inventory_id THEN
        v_error_msg := FORMAT(
            'Self-transfer not allowed: source and target are both inventory %s.',
            source_inventory_id
        );
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Minimum quantity guard
    IF quantity_to_transfer < 1 THEN
        v_error_msg := FORMAT(
            'Invalid quantity %s: minimum transfer quantity is 1.',
            quantity_to_transfer
        );
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Maximum quantity guard
    IF quantity_to_transfer > 500 THEN
        v_error_msg := FORMAT(
            'Invalid quantity %s: maximum transfer quantity per operation is 500.',
            quantity_to_transfer
        );
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ===========================================================
    -- STEP A-2 : EXISTENCE VALIDATION
    -- ===========================================================

    -- Verify source inventory exists
    SELECT EXISTS (
        SELECT 1 FROM lego_inventories WHERE id = source_inventory_id
    ) INTO v_source_inv_exists;

    IF NOT v_source_inv_exists THEN
        v_error_msg := FORMAT(
            'Source inventory ID %s does not exist in lego_inventories.',
            source_inventory_id
        );
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Verify target inventory exists
    SELECT EXISTS (
        SELECT 1 FROM lego_inventories WHERE id = target_inventory_id
    ) INTO v_target_inv_exists;

    IF NOT v_target_inv_exists THEN
        v_error_msg := FORMAT(
            'Target inventory ID %s does not exist in lego_inventories.',
            target_inventory_id
        );
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Verify part exists in lego_parts catalog
    SELECT EXISTS (
        SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num
    ) INTO v_part_exists;

    IF NOT v_part_exists THEN
        v_error_msg := FORMAT(
            'Part "%s" does not exist in lego_parts catalog.',
            part_to_transfer_num
        );
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Verify color exists in lego_colors
    SELECT EXISTS (
        SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id
    ) INTO v_color_exists;

    IF NOT v_color_exists THEN
        v_error_msg := FORMAT(
            'Color ID %s does not exist in lego_colors.',
            color_to_transfer_id
        );
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ===========================================================
    -- STEP A-3 : LOCK SOURCE ROW & VERIFY SUFFICIENT QUANTITY
    -- Locks prevent concurrent transfers from racing on the same
    -- source row.
    -- ===========================================================

    SELECT quantity, is_spare
      INTO v_source_qty, v_source_is_spare
      FROM lego_inventory_parts
     WHERE inventory_id = source_inventory_id
       AND part_num     = part_to_transfer_num
       AND color_id     = color_to_transfer_id
       FOR UPDATE;          -- row-level lock

    -- Part not present in source at all
    IF NOT FOUND THEN
        v_error_msg := FORMAT(
            'Part "%s" with color_id %s not found in source inventory %s.',
            part_to_transfer_num, color_to_transfer_id, source_inventory_id
        );
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Insufficient quantity
    IF v_source_qty < quantity_to_transfer THEN
        v_error_msg := FORMAT(
            'Insufficient quantity in source inventory %s: requested %s but only %s available '
            || '(part "%s", color_id %s).',
            source_inventory_id, quantity_to_transfer, v_source_qty,
            part_to_transfer_num, color_to_transfer_id
        );
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Also lock any existing target row to prevent concurrent inserts
    SELECT quantity
      INTO v_target_qty
      FROM lego_inventory_parts
     WHERE inventory_id = target_inventory_id
       AND part_num     = part_to_transfer_num
       AND color_id     = color_to_transfer_id
       FOR UPDATE;          -- advisory lock even if not found

    -- ===========================================================
    -- STEP B : UPDATE SOURCE INVENTORY
    -- ===========================================================

    IF v_source_qty = quantity_to_transfer THEN
        -- Remove the row entirely when quantity drops to zero
        DELETE FROM lego_inventory_parts
         WHERE inventory_id = source_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    ELSE
        -- Decrement quantity
        UPDATE lego_inventory_parts
           SET quantity = quantity - quantity_to_transfer
         WHERE inventory_id = source_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    END IF;

    -- ===========================================================
    -- STEP C : UPDATE TARGET INVENTORY
    -- ===========================================================

    IF v_target_qty IS NOT NULL THEN
        -- Part already exists in target → increment quantity
        UPDATE lego_inventory_parts
           SET quantity = quantity + quantity_to_transfer
         WHERE inventory_id = target_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    ELSE
        -- Part does not exist in target → insert new row,
        -- preserving the is_spare flag from the source record.
        INSERT INTO lego_inventory_parts (
            inventory_id, part_num, color_id, quantity, is_spare
        ) VALUES (
            target_inventory_id,
            part_to_transfer_num,
            color_to_transfer_id,
            quantity_to_transfer,
            v_source_is_spare       -- carry over spare flag from source
        );
    END IF;

    -- ===========================================================
    -- STEP D : AUDIT – LOG SUCCESSFUL TRANSFER
    -- ===========================================================

    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id,
        part_num, color_id,
        quantity_transferred, transfer_reason,
        transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id,
        part_to_transfer_num, color_to_transfer_id,
        quantity_to_transfer, transfer_reason,
        'success', NULL
    );

    -- ===========================================================
    -- Build and return the success message
    -- ===========================================================

    v_result_msg := FORMAT(
        'Successfully transferred %s parts (%s, color_id: %s) '
        || 'from inventory %s to inventory %s. Reason: %s',
        quantity_to_transfer,
        part_to_transfer_num,
        color_to_transfer_id,
        source_inventory_id,
        target_inventory_id,
        transfer_reason
    );

    RETURN v_result_msg;

EXCEPTION
    -- Re-raise our own exceptions as-is (they already logged the failure).
    WHEN OTHERS THEN
        -- If the exception was thrown BEFORE we could log it (e.g. an
        -- unexpected internal DB error during the UPDATE/INSERT phase),
        -- capture and re-raise.  Our explicit RAISE EXCEPTIONs already
        -- wrote to the log, so this is a safety net only.
        RAISE;
END;
$$;

COMMENT ON FUNCTION transfer_parts(INTEGER, INTEGER, VARCHAR, INTEGER, INTEGER, VARCHAR) IS
'Transfers LEGO inventory parts between two inventories with:
  • Self-transfer prevention
  • Quantity range enforcement (1–500)
  • Existence checks (inventories, part, color)
  • Sufficient-stock check
  • Row-level locking to prevent race conditions
  • Atomic source decrement / target increment (or delete/insert)
  • Full audit logging in inventory_transfer_log for every attempt';
"}

