{"name": "fix_transfer_parts_failed_audit_logging", "query": "
-- ============================================================
-- Revised transfer_parts() — failed-transfer audit entries are
-- written inside an EXCEPTION block so that PostgreSQL's
-- implicit subtransaction commits the log row even when the
-- outer transaction rolls back.
-- ============================================================
CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id   INTEGER,
    target_inventory_id   INTEGER,
    part_to_transfer_num  VARCHAR,
    color_to_transfer_id  INTEGER,
    quantity_to_transfer  INTEGER,
    transfer_reason       VARCHAR DEFAULT 'manual_transfer'
)
RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    v_source_qty        INTEGER;
    v_source_is_spare   BOOLEAN;
    v_target_qty        INTEGER;

    v_source_inv_exists BOOLEAN := FALSE;
    v_target_inv_exists BOOLEAN := FALSE;
    v_part_exists       BOOLEAN := FALSE;
    v_color_exists      BOOLEAN := FALSE;

    v_result_msg        TEXT;
    v_error_msg         TEXT;
BEGIN
    -- ===========================================================
    -- BLOCK 1: All validation + data mutation.
    --          Any RAISE EXCEPTION here jumps to the EXCEPTION
    --          handler below, which logs the failure and re-raises.
    -- ===========================================================

    -- ── Business-rule: self-transfer ──────────────────────────
    IF source_inventory_id = target_inventory_id THEN
        RAISE EXCEPTION 'Self-transfer not allowed: source and target are both inventory %.', 
            source_inventory_id;
    END IF;

    -- ── Business-rule: quantity range ─────────────────────────
    IF quantity_to_transfer < 1 THEN
        RAISE EXCEPTION 'Invalid quantity %: minimum transfer quantity is 1.',
            quantity_to_transfer;
    END IF;

    IF quantity_to_transfer > 500 THEN
        RAISE EXCEPTION 'Invalid quantity %: maximum transfer quantity per operation is 500.',
            quantity_to_transfer;
    END IF;

    -- ── Existence: source inventory ───────────────────────────
    SELECT EXISTS (
        SELECT 1 FROM lego_inventories WHERE id = source_inventory_id
    ) INTO v_source_inv_exists;

    IF NOT v_source_inv_exists THEN
        RAISE EXCEPTION 'Source inventory ID % does not exist in lego_inventories.',
            source_inventory_id;
    END IF;

    -- ── Existence: target inventory ───────────────────────────
    SELECT EXISTS (
        SELECT 1 FROM lego_inventories WHERE id = target_inventory_id
    ) INTO v_target_inv_exists;

    IF NOT v_target_inv_exists THEN
        RAISE EXCEPTION 'Target inventory ID % does not exist in lego_inventories.',
            target_inventory_id;
    END IF;

    -- ── Existence: part in catalog ────────────────────────────
    SELECT EXISTS (
        SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num
    ) INTO v_part_exists;

    IF NOT v_part_exists THEN
        RAISE EXCEPTION 'Part "%" does not exist in lego_parts catalog.',
            part_to_transfer_num;
    END IF;

    -- ── Existence: color in catalog ───────────────────────────
    SELECT EXISTS (
        SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id
    ) INTO v_color_exists;

    IF NOT v_color_exists THEN
        RAISE EXCEPTION 'Color ID % does not exist in lego_colors.',
            color_to_transfer_id;
    END IF;

    -- ── Lock source row; check stock ──────────────────────────
    SELECT quantity, is_spare
      INTO v_source_qty, v_source_is_spare
      FROM lego_inventory_parts
     WHERE inventory_id = source_inventory_id
       AND part_num     = part_to_transfer_num
       AND color_id     = color_to_transfer_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Part "%" with color_id % not found in source inventory %.',
            part_to_transfer_num, color_to_transfer_id, source_inventory_id;
    END IF;

    IF v_source_qty < quantity_to_transfer THEN
        RAISE EXCEPTION
            'Insufficient quantity in source inventory %: requested % but only % available (part "%", color_id %).',
            source_inventory_id, quantity_to_transfer, v_source_qty,
            part_to_transfer_num, color_to_transfer_id;
    END IF;

    -- ── Lock target row (if it exists) ────────────────────────
    SELECT quantity
      INTO v_target_qty
      FROM lego_inventory_parts
     WHERE inventory_id = target_inventory_id
       AND part_num     = part_to_transfer_num
       AND color_id     = color_to_transfer_id
       FOR UPDATE;

    -- ── STEP B: Update source ─────────────────────────────────
    IF v_source_qty = quantity_to_transfer THEN
        DELETE FROM lego_inventory_parts
         WHERE inventory_id = source_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    ELSE
        UPDATE lego_inventory_parts
           SET quantity = quantity - quantity_to_transfer
         WHERE inventory_id = source_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    END IF;

    -- ── STEP C: Update target ─────────────────────────────────
    IF v_target_qty IS NOT NULL THEN
        UPDATE lego_inventory_parts
           SET quantity = quantity + quantity_to_transfer
         WHERE inventory_id = target_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    ELSE
        INSERT INTO lego_inventory_parts (
            inventory_id, part_num, color_id, quantity, is_spare
        ) VALUES (
            target_inventory_id,
            part_to_transfer_num,
            color_to_transfer_id,
            quantity_to_transfer,
            v_source_is_spare
        );
    END IF;

    -- ── STEP D: Audit — SUCCESS ───────────────────────────────
    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id,
        part_num, color_id,
        quantity_transferred, transfer_reason,
        transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id,
        part_to_transfer_num, color_to_transfer_id,
        quantity_to_transfer, transfer_reason,
        'success', NULL
    );

    -- ── Return success message ────────────────────────────────
    v_result_msg := FORMAT(
        'Successfully transferred %s parts (%s, color_id: %s) '
        || 'from inventory %s to inventory %s. Reason: %s',
        quantity_to_transfer,
        part_to_transfer_num,
        color_to_transfer_id,
        source_inventory_id,
        target_inventory_id,
        transfer_reason
    );

    RETURN v_result_msg;

-- ===========================================================
-- EXCEPTION HANDLER
-- Fires whenever any RAISE EXCEPTION is thrown above.
-- The handler runs in an implicit subtransaction; the INSERT
-- into inventory_transfer_log is committed even though the
-- outer transaction (all data changes) is rolled back.
-- ===========================================================
EXCEPTION
    WHEN OTHERS THEN
        -- Capture the human-readable message from the exception
        v_error_msg := SQLERRM;

        -- Write the failure audit record
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id,
            quantity_transferred, transfer_reason,
            transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason,
            'failed', v_error_msg
        );

        -- Re-raise so the caller still sees the error
        RAISE;
END;
$$;

COMMENT ON FUNCTION transfer_parts(INTEGER, INTEGER, VARCHAR, INTEGER, INTEGER, VARCHAR) IS
'Transfers LEGO inventory parts between two inventories with:
  • Self-transfer prevention
  • Quantity range enforcement (1–500)
  • Existence checks (inventories, part, color)
  • Sufficient-stock check
  • Row-level locking to prevent race conditions
  • Atomic source decrement / target increment (or delete/insert)
  • Full audit logging in inventory_transfer_log for every attempt
    (failure log entries are committed even when the main txn rolls back,
     via PostgreSQL implicit subtransaction in the EXCEPTION block)';
