    SELECT EXISTS (
        SELECT 1 FROM lego_inventories WHERE id = source_inventory_id
    ) INTO v_source_inv_exists;

    IF NOT v_source_inv_exists THEN
        RAISE EXCEPTION 'Source inventory ID % does not exist in lego_inventories.',
            source_inventory_id;
    END IF;

    -- ── Existence: target inventory ───────────────────────────
    SELECT EXISTS (
        SELECT 1 FROM lego_inventories WHERE id = target_inventory_id
    ) INTO v_target_inv_exists;

    IF NOT v_target_inv_exists THEN
        RAISE EXCEPTION 'Target inventory ID % does not exist in lego_inventories.',
            target_inventory_id;
    END IF;

    -- ── Existence: part in catalog ────────────────────────────
    SELECT EXISTS (
        SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num
    ) INTO v_part_exists;

    IF NOT v_part_exists THEN
        RAISE EXCEPTION 'Part "%" does not exist in lego_parts catalog.',
            part_to_transfer_num;
    END IF;

    -- ── Existence: color in catalog ───────────────────────────
    SELECT EXISTS (
        SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id
    ) INTO v_color_exists;

    IF NOT v_color_exists THEN
        RAISE EXCEPTION 'Color ID % does not exist in lego_colors.',
            color_to_transfer_id;
    END IF;

    -- ── Lock source row; verify stock ─────────────────────────
    SELECT quantity, is_spare
      INTO v_source_qty, v_source_is_spare
      FROM lego_inventory_parts
     WHERE inventory_id = source_inventory_id
       AND part_num     = part_to_transfer_num
       AND color_id     = color_to_transfer_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Part "%" with color_id % not found in source inventory %.',
            part_to_transfer_num, color_to_transfer_id, source_inventory_id;
    END IF;

    IF v_source_qty < quantity_to_transfer THEN
        RAISE EXCEPTION
            'Insufficient quantity in source inventory %: requested % but only % available (part "%", color_id %).',
            source_inventory_id, quantity_to_transfer, v_source_qty,
            part_to_transfer_num, color_to_transfer_id;
    END IF;

    -- ── Lock target row (if any) ──────────────────────────────
    SELECT quantity
      INTO v_target_qty
      FROM lego_inventory_parts
     WHERE inventory_id = target_inventory_id
       AND part_num     = part_to_transfer_num
       AND color_id     = color_to_transfer_id
       FOR UPDATE;

    -- ── STEP B: Update source ─────────────────────────────────
    IF v_source_qty = quantity_to_transfer THEN
        DELETE FROM lego_inventory_parts
         WHERE inventory_id = source_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    ELSE
        UPDATE lego_inventory_parts
           SET quantity = quantity - quantity_to_transfer
         WHERE inventory_id = source_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    END IF;

    -- ── STEP C: Update target ─────────────────────────────────
    IF v_target_qty IS NOT NULL THEN
        UPDATE lego_inventory_parts
           SET quantity = quantity + quantity_to_transfer
         WHERE inventory_id = target_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    ELSE
        INSERT INTO lego_inventory_parts (
            inventory_id, part_num, color_id, quantity, is_spare
        ) VALUES (
            target_inventory_id,
            part_to_transfer_num,
            color_to_transfer_id,
            quantity_to_transfer,
            v_source_is_spare
        );
    END IF;

    -- ── STEP D: Audit — SUCCESS (inline, same transaction) ───
    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id,
        part_num, color_id,
        quantity_transferred, transfer_reason,
        transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id,
        part_to_transfer_num, color_to_transfer_id,
        quantity_to_transfer, transfer_reason,
        'success', NULL
    );

    -- ── Return ────────────────────────────────────────────────
    v_result_msg := FORMAT(
        'Successfully transferred %s parts (%s, color_id: %s) '
        || 'from inventory %s to inventory %s. Reason: %s',
        quantity_to_transfer,
        part_to_transfer_num,
        color_to_transfer_id,
        source_inventory_id,
        target_inventory_id,
        transfer_reason
    );

    RETURN v_result_msg;

-- ===========================================================
-- EXCEPTION HANDLER — runs in its own subtransaction.
-- Uses dblink to open a SEPARATE connection and INSERT the
-- failure log row in an independent transaction that commits
-- even though the caller's transaction is about to roll back.
-- ===========================================================
EXCEPTION
    WHEN OTHERS THEN
        v_error_msg := SQLERRM;

        -- Build the autonomous INSERT via dblink
        v_log_sql := format(
            $sql$
            INSERT INTO public.inventory_transfer_log (
                source_inventory_id, target_inventory_id,
                part_num, color_id,
                quantity_transferred, transfer_reason,
                transfer_status, error_message
            ) VALUES (%L, %L, %L, %L, %L, %L, 'failed', %L)
            $sql$,
            source_inventory_id,
            target_inventory_id,
            part_to_transfer_num,
            color_to_transfer_id,
            quantity_to_transfer,
            transfer_reason,
            v_error_msg
        );

        -- Fire-and-forget via dblink (auto-commits in its own session)
        BEGIN
            PERFORM dblink_exec(
                format(
                    'host=localhost port=5432 dbname=%s user=%s password=%s',
                    current_database(),
                    current_user,
                    -- Retrieve password from pg_shadow (superuser only)
                    -- On Supabase, use the service role connection string instead
                    'postgres'
                ),
                v_log_sql
            );
        EXCEPTION WHEN OTHERS THEN
            -- If dblink fails (e.g. auth), fall back to raising a notice.
            -- The original exception is still re-raised below.
            RAISE WARNING 'transfer_parts: could not write failure audit log via dblink: %', SQLERRM;
        END;

        -- Always re-raise the original error
        RAISE;
END;
$$;
"}

